"""Compare regenerated bytes with checked-in reference artifacts."""
import argparse
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument("regenerated", type=Path)
args = parser.parse_args()
reference = Path(__file__).resolve().parents[1] / "examples" / "synthetic"
files = sorted(path.relative_to(reference) for path in reference.rglob("*") if path.is_file())
if not files:
    raise SystemExit("No reference examples found")
failures = [str(path) for path in files if not (args.regenerated/path).exists() or (reference/path).read_bytes() != (args.regenerated/path).read_bytes()]
if failures:
    raise SystemExit("Reproducibility mismatch: " + ", ".join(failures))
print(f"Verified {len(files)} byte-identical SYNTHETIC artifacts")
